mapper.select:
SELECT cl.id, cl.title, cl.summary, cl.create_time, cl.is_top, cl.is_anonymous, cl.status, cl.type, cl.user_id, u.userName as realName, u.identity, CASE WHEN cl.is_anonymous = 0 THEN u.userName ELSE '匿名' END AS userName FROM confession_log cl LEFT JOIN user u ON cl.user_id = u.id
AND cl.title LIKE CONCAT('%', #{title}, '%')
AND cl.type = #{type}
AND cl.create_time >= #{createTimeStart}
AND cl.create_time <= #{createTimeEnd}
AND u.userName LIKE CONCAT('%', #{userName}, '%')
AND cl.status = #{status}
ORDER BY cl.is_top DESC, cl.create_time DESC
